import threading
import time
import smtplib
import ssl
from email.mime.text import MIMEText
from collections import defaultdict
from dataclasses import dataclass, field
from typing import Dict, List, Optional
import logging

logger = logging.getLogger(__name__)

@dataclass
class RateLimitState:
    tokens: float = 10.0
    max_tokens: float = 10.0
    refill_rate: float = 1.0
    last_refill: float = field(default_factory=time.time)
    lock: threading.Lock = field(default_factory=threading.Lock)

    def consume(self, count: float = 1.0) -> bool:
        with self.lock:
            now = time.time()
            elapsed = now - self.last_refill
            self.tokens = min(self.max_tokens, self.tokens + elapsed * self.refill_rate)
            self.last_refill = now
            if self.tokens >= count:
                self.tokens -= count
                return True
            return False


class EmailDeliveryRecord:
    def __init__(self):
        self._lock = threading.Lock()
        self._sent_ids: Dict[str, bool] = {}
        self._pending_callbacks: Dict[str, List[callable]] = defaultdict(list)

    def mark_sending(self, message_id: str) -> bool:
        with self._lock:
            if message_id in self._sent_ids:
                return False
            self._sent_ids[message_id] = False
            return True

    def mark_complete(self, message_id: str, success: bool):
        callbacks = []
        with self._lock:
            self._sent_ids[message_id] = success
            callbacks = self._pending_callbacks.pop(message_id, [])
        for cb in callbacks:
            cb(message_id, success)

    def register_callback(self, message_id: str, callback: callable):
        with self._lock:
            if message_id in self._sent_ids and self._sent_ids[message_id]:
                pass
            else:
                self._pending_callbacks[message_id].append(callback)

    def is_complete(self, message_id: str) -> bool:
        with self._lock:
            return self._sent_ids.get(message_id, False)


class RetryPolicy:
    def __init__(self, max_retries: int = 3, backoff_base: float = 0.5):
        self.max_retries = max_retries
        self.backoff_base = backoff_base

    def get_delay(self, attempt: int) -> float:
        return self.backoff_base * (2 ** attempt)

    def should_retry(self, attempt: int, exception: Exception) -> bool:
        if attempt >= self.max_retries:
            return False
        if isinstance(exception, smtplib.SMTPRecipientsRefused):
            return False
        return True


class EmailService:
    def __init__(self, smtp_host: str, smtp_port: int, username: str, password: str):
        self._smtp_host = smtp_host
        self._smtp_port = smtp_port
        self._username = username
        self._password = password
        self._rate_limits: Dict[str, RateLimitState] = defaultdict(RateLimitState)
        self._delivery_record = EmailDeliveryRecord()
        self._retry_policy = RetryPolicy()
        self._service_lock = threading.Lock()
        self._active_sends: Dict[str, threading.Event] = {}

    def _get_smtp_connection(self) -> smtplib.SMTP:
        conn = smtplib.SMTP(self._smtp_host, self._smtp_port)
        context = ssl.create_default_context()
        conn.starttls(context=context)
        conn.login(self._username, self._password)
        return conn

    def _do_send(self, message_id: str, sender: str, recipient: str, subject: str, body: str) -> bool:
        msg = MIMEText(body)
        msg['Subject'] = subject
        msg['From'] = sender
        msg['To'] = recipient
        msg['Message-ID'] = message_id

        attempt = 0
        while True:
            try:
                conn = self._get_smtp_connection()
                conn.sendmail(sender, [recipient], msg.as_string())
                conn.quit()
                return True
            except Exception as e:
                if self._retry_policy.should_retry(attempt, e):
                    delay = self._retry_policy.get_delay(attempt)
                    time.sleep(delay)
                    attempt += 1
                else:
                    logger.error(f"Failed to send {message_id}: {e}")
                    return False

    def send_email(self, message_id: str, sender: str, recipient: str, subject: str, body: str) -> bool:
        with self._service_lock:
            if not self._rate_limits[sender].consume():
                logger.warning(f"Rate limit exceeded for {sender}")
                return False

            if not self._delivery_record.mark_sending(message_id):
                logger.info(f"Message {message_id} already processed")
                return self._delivery_record.is_complete(message_id)

            event = threading.Event()
            self._active_sends[message_id] = event

        try:
            success = self._do_send(message_id, sender, recipient, subject, body)
            self._delivery_record.mark_complete(message_id, success)
            return success
        finally:
            with self._service_lock:
                event.set()
                del self._active_sends[message_id]

    def send_email_with_notification(self, message_id: str, sender: str, recipient: str,
                                      subject: str, body: str, on_complete: callable) -> bool:
        self._delivery_record.register_callback(message_id, on_complete)
        return self.send_email(message_id, sender, recipient, subject, body)

    def send_batch(self, emails: List[dict], sender: str) -> Dict[str, bool]:
        results = {}
        for email_data in emails:
            mid = email_data['message_id']
            results[mid] = self.send_email(
                mid, sender, email_data['recipient'],
                email_data['subject'], email_data['body']
            )
        return results

    def send_with_followup(self, message_id: str, sender: str, recipient: str,
                           subject: str, body: str, followup_body: str) -> bool:
        """Send an email and if successful, schedule a followup on a separate thread."""
        def on_first_complete(mid, success):
            if success:
                followup_id = f"{mid}_followup"
                t = threading.Thread(target=self.send_email, args=(
                    followup_id, sender, recipient,
                    f"Re: {subject}", followup_body
                ))
                t.daemon = True
                t.start()

        return self.send_email_with_notification(
            message_id, sender, recipient, subject, body, on_first_complete
        )
